/* ERAVOS runtime — catalog.js → window.Catalog (spec eravos.p38.catalog). Domain-free: it knows tools only as the
 * metadata the tools folder hands it (tools/catalog.js, GENERATED by build/index-tools.mjs) — never by name.
 *
 * Sovereign by default: a fresh profile installs NOTHING. Boot loads only the domains and tools you installed; installing
 * later loads the same files in order (one FIFO queue), the way a dropped pack does. A profile that used ERAVOS before the
 * catalog existed keeps everything (all: true) — nothing you made stops opening.
 *
 *   Catalog.domain(meta) / Catalog.tool(meta)   ← tools/catalog.js        meta: { id, label, icon, … files:[[kind,url]] }
 *   Catalog.boot(domainIds)                       ← tools/index.js (while the page parses)
 *   Catalog.take(toolId)                          ← each domain's generated tools/index.js: load this tool now?
 *   Catalog.install(ids, K) → Promise<string[]>   load + remember (a domain's core comes with its first tool)
 *   Catalog.remove(id)                            forget (code cannot be unloaded: gone from ＋ Add now, from memory next start)
 *   Catalog.ensure(ids, K)                        a project names tools you have not installed → install them, say which
 *   Catalog.load(url, isCss)                      the ordered loader every loader uses (document.write while parsing)
 * State: localStorage 'eravos.catalog.v1' — read synchronously at boot (IndexedDB is async; boot cannot wait for it). */
(function (global) {
  'use strict';
  const doc = global.document, KEY = 'eravos.catalog.v1';
  const domains = new Map(), tools = new Map(), loadedTools = new Set(), loadedDomains = new Set(), failed = [];
  const listeners = new Set();
  // ---------------------------------------------------------------- state
  function read() { try { return JSON.parse(global.localStorage.getItem(KEY)); } catch (e) { return null; } }
  function keep() { try { global.localStorage.setItem(KEY, JSON.stringify(rec)); } catch (e) { /* storage blocked: kept until the page closes */ } }
  let rec = read();
  if (!rec || !Array.isArray(rec.installed)) {
    // first start with a catalog: someone who already used ERAVOS here keeps every tool; a new profile starts empty
    let used = false; try { for (let i = 0; i < global.localStorage.length; i++) { const k = global.localStorage.key(i); if (k && k !== KEY && /^eravos/i.test(k)) { used = true; break; } } } catch (e) {}
    rec = { all: used, installed: [], removed: [] }; keep();
  }
  rec.removed = rec.removed || [];
  const all = () => global.ERAVOS_CATALOG_ALL === true || !!rec.all;
  const isInstalled = (id) => !rec.removed.includes(id) && (all() || rec.installed.includes(id));
  // ---------------------------------------------------------------- ordered loading (parse time: document.write · later: FIFO)
  const queue = []; let busy = false, waiters = [];
  const parsing = () => !!doc && doc.readyState === 'loading';
  function load(url, css) {
    if (parsing()) { doc.write(css ? '<link rel="stylesheet" href="' + url + '">' : '<script src="' + url + '"><\/script>'); return; }
    queue.push({ url, css }); pump();
  }
  function pump() {
    if (busy) return;
    const it = queue.shift();
    if (!it) { const w = waiters; waiters = []; w.forEach(f => f()); return; }
    busy = true; const next = () => { busy = false; pump(); };
    if (it.css) { const l = doc.createElement('link'); l.rel = 'stylesheet'; l.href = it.url; doc.head.appendChild(l); next(); return; }
    const s = doc.createElement('script'); s.src = it.url; s.onload = next; s.onerror = () => { failed.push(it.url); next(); };
    doc.head.appendChild(s);   // a script that queues more (a domain loader) queues them before its own onload → order holds
  }
  const drained = () => new Promise(r => { if (!busy && !queue.length) r(); else waiters.push(r); });
  // ---------------------------------------------------------------- domains + tools
  function needDomains() {   // installed tools' domains + the domains they speak through (ports), in boot order
    const want = new Set(rec.domainsChosen || []);
    tools.forEach(t => { if (isInstalled(t.id)) want.add(t.domain); });
    let grew = true; while (grew) { grew = false; Array.from(want).forEach(d => ((domains.get(d) || {}).ports || []).forEach(p => { if (!want.has(p)) { want.add(p); grew = true; } })); }
    return want;
  }
  function loadDomain(id, seen) {   // the domains it speaks through (its ports) load first
    const d = domains.get(id); if (!d || loadedDomains.has(id)) return false; seen = seen || new Set(); if (seen.has(id)) return false; seen.add(id);
    (d.ports || []).forEach(p => { if (p !== id) loadDomain(p, seen); });
    loadedDomains.add(id); load(d.loader); return true;
  }
  function loadTool(id) { const t = tools.get(id); if (!t || loadedTools.has(id)) return false; loadedTools.add(id); t.files.forEach(f => load(f[1], f[0] === 'css')); return true; }
  const emit = () => listeners.forEach(fn => { try { fn(); } catch (e) {} });
  const C = global.Catalog = {
    KEY, load,
    domain(meta) { domains.set(meta.id, Object.assign({ ports: [], starter: [] }, meta)); },
    tool(meta) { tools.set(meta.id, meta); },
    boot(order) {
      if (all()) { (order || Array.from(domains.keys())).forEach(id => { if (domains.has(id)) loadDomain(id); else if (global.ERAVOS_TOOLS) { loadedDomains.add(id); load(global.ERAVOS_TOOLS + id + '/index.js'); } }); return; }
      const want = needDomains(); (order || Array.from(domains.keys())).forEach(id => { if (want.has(id)) loadDomain(id); });
    },
    take(id) { if (!isInstalled(id) || loadedTools.has(id)) return false; loadedTools.add(id); return true; },
    async install(ids, K) {
      ids = [].concat(ids).filter(id => tools.has(id));
      const fresh = ids.filter(id => !loadedTools.has(id));
      ids.forEach(id => { if (!rec.installed.includes(id)) rec.installed.push(id); rec.removed = rec.removed.filter(x => x !== id); }); keep();
      const before = new Set(loadedDomains);
      needDomains().forEach(d => loadDomain(d));            // a new domain's loader takes its own (now installed) tools
      fresh.forEach(id => { if (before.has(tools.get(id).domain)) loadTool(id); });
      await drained();
      if (K && K.domains && K.domains.prepare) K.domains.prepare();
      emit();
      return fresh.filter(id => global.OrganismFactory && global.OrganismFactory.def(id));
    },
    remove(id) {
      if (rec.all) { rec.all = false; rec.installed = Array.from(tools.keys()).filter(t => loadedTools.has(t)); }
      rec.installed = rec.installed.filter(x => x !== id); if (!rec.removed.includes(id)) rec.removed.push(id); keep(); emit();
    },
    async ensure(ids, K) {   // a project needs tools this canvas has not installed: install the ones the catalog knows, name them
      const miss = Array.from(new Set(ids)).filter(id => tools.has(id) && !(global.OrganismFactory && global.OrganismFactory.def(id)));
      if (!miss.length) return [];
      const got = await C.install(miss, K);
      return got.map(id => tools.get(id).label || id);
    },
    chooseDomain(id) { rec.domainsChosen = Array.from(new Set((rec.domainsChosen || []).concat(id))); keep(); },
    domains: () => Array.from(domains.values()).map(d => Object.assign({}, d, { loaded: loadedDomains.has(d.id), installed: Array.from(tools.values()).filter(t => t.domain === d.id && isInstalled(t.id)).length, total: Array.from(tools.values()).filter(t => t.domain === d.id).length })),
    tools: () => Array.from(tools.values()),
    meta: (id) => tools.get(id) || null,
    isInstalled, isLoaded: (id) => loadedTools.has(id), isRemoved: (id) => rec.removed.includes(id),
    available: () => Array.from(tools.values()).filter(t => !loadedTools.has(t.id) && !(global.OrganismFactory && global.OrganismFactory.def(t.id))),
    allMode: all, state: () => JSON.parse(JSON.stringify(rec)), failed: () => failed.slice(),
    onChange(fn) { listeners.add(fn); return () => listeners.delete(fn); },
    drained,
  };
  global.ERAVOS_LOAD = load;
})(typeof window !== 'undefined' ? window : globalThis);
